package com.bankpricechanges;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bankpricechanges")
public interface BankPriceChangesConfig extends Config
{
    enum PriceMode
    {
        HIGH,
        LOW
    }

    enum TimePeriod
    {
        FIVE_MIN("5m"),
        ONE_HOUR("1h"),
        SIX_HOURS("6h"),
        TWENTY_FOUR_HOURS("24h"),
        ONE_WEEK("1w"),
        ONE_MONTH("1mo"),
        ONE_YEAR("1yr");

        private final String label;

        TimePeriod(String label)
        {
            this.label = label;
        }

        @Override
        public String toString()
        {
            return label;
        }
    }

    enum PanelItemCount
    {
        FIVE(5),
        TEN(10);

        final int count;

        PanelItemCount(int count)
        {
            this.count = count;
        }

        @Override
        public String toString()
        {
            return String.valueOf(count);
        }
    }

    // ── Hidden panel state (persisted, not shown in config panel UI) ─────────

    @ConfigItem(keyName = "showByPercent",      name = "", description = "", hidden = true)
    default boolean showByPercent() { return false; }

    @ConfigItem(keyName = "priceMode",          name = "", description = "", hidden = true)
    default PriceMode priceMode() { return PriceMode.LOW; }

    @ConfigItem(keyName = "minThreshold",       name = "", description = "", hidden = true)
    default double minThreshold() { return 0.0; }

    @ConfigItem(keyName = "timePeriod",         name = "", description = "", hidden = true)
    default TimePeriod timePeriod() { return TimePeriod.TWENTY_FOUR_HOURS; }

    @ConfigItem(keyName = "panelItemCount",     name = "", description = "", hidden = true)
    default PanelItemCount panelItemCount() { return PanelItemCount.FIVE; }

    @ConfigItem(keyName = "includePlaceholders",name = "", description = "", hidden = true)
    default boolean includePlaceholders() { return true; }

    @ConfigItem(keyName = "minGpThreshold",     name = "", description = "", hidden = true)
    default int minGpThreshold() { return 0; }

    // ── Visible config panel setting ──────────────────────────────────────────

    @ConfigItem(
        keyName = "showBankOverlay",
        name = "Show Bank Overlay",
        description = "Show price change labels on bank items"
    )
    default boolean showBankOverlay() { return true; }
}

package com.bankpricechanges;

import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;

public class BankPriceChangesOverlay extends WidgetItemOverlay
{
    private final BankPriceChangesPlugin plugin;
    private final BankPriceChangesConfig config;
    private final ItemManager itemManager;

    @Inject
    BankPriceChangesOverlay(BankPriceChangesPlugin plugin, BankPriceChangesConfig config, ItemManager itemManager)
    {
        this.plugin = plugin;
        this.config = config;
        this.itemManager = itemManager;
        showOnBank();
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (!config.showBankOverlay())
        {
            return;
        }

        if (!config.includePlaceholders()
                && itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1)
        {
            return;
        }

        PriceData data = plugin.getPriceChange(itemManager.canonicalize(itemId));
        if (data == null)
        {
            return;
        }

        BankPriceChangesConfig.PriceMode priceMode = config.priceMode();

        if (Math.abs(data.getChangePct(priceMode)) < config.minThreshold())
        {
            return;
        }

        if (Math.abs(data.getChange(priceMode)) < config.minGpThreshold())
        {
            return;
        }

        int change = data.getChange(priceMode);
        Color color = change >= 0 ? Color.GREEN : Color.RED;
        String sign = change >= 0 ? "+" : "";

        String text = config.showByPercent()
            ? sign + String.format("%.1f%%", data.getChangePct(priceMode))
            : sign + PriceFormatter.formatGp(change);

        Rectangle bounds = widgetItem.getCanvasBounds();
        graphics.setFont(FontManager.getRunescapeSmallFont());
        drawText(graphics, text, color, bounds.x + 1, bounds.y + bounds.height - 1);
    }

    private void drawText(Graphics2D graphics, String text, Color color, int x, int y)
    {
        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x + 1, y + 1);
        graphics.setColor(color);
        graphics.drawString(text, x, y);
    }
}

package com.bankpricechanges;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.List;

public class BankPriceChangesPanel extends PluginPanel
{
    private static final Color COLOR_GAIN  = new Color(0, 200, 0);
    private static final Color COLOR_LOSS  = Color.RED;
    private static final Color COLOR_LABEL = new Color(150, 150, 150);
    private static final String CONFIG_GROUP = "bankpricechanges";

    private static final Map<BankPriceChangesConfig.TimePeriod, String> PERIOD_LABELS;
    static {
        PERIOD_LABELS = new LinkedHashMap<>();
        PERIOD_LABELS.put(BankPriceChangesConfig.TimePeriod.FIVE_MIN,          "5 min");
        PERIOD_LABELS.put(BankPriceChangesConfig.TimePeriod.ONE_HOUR,          "1 hour");
        PERIOD_LABELS.put(BankPriceChangesConfig.TimePeriod.SIX_HOURS,        "6 hours");
        PERIOD_LABELS.put(BankPriceChangesConfig.TimePeriod.TWENTY_FOUR_HOURS,"24 hours");
        PERIOD_LABELS.put(BankPriceChangesConfig.TimePeriod.ONE_WEEK,         "1 week");
        PERIOD_LABELS.put(BankPriceChangesConfig.TimePeriod.ONE_MONTH,        "1 month");
        PERIOD_LABELS.put(BankPriceChangesConfig.TimePeriod.ONE_YEAR,         "1 year");
    }

    private static final String[] SORT_OPTIONS       = {"GP change", "% change"};
    private static final String[] PRICE_MODE_OPTIONS = {"Sell offer (low)", "Buy offer (high)"};

    private final BankPriceChangesPlugin plugin;
    private final BankPriceChangesConfig config;
    private final ItemManager itemManager;
    private final ConfigManager configManager;

    private boolean showGainers   = true;
    private boolean showByPercent = false;
    private int displayCount;

    private List<PanelItemEntry> allEntries = new ArrayList<>();
    private JPanel itemListPanel;
    private JLabel updatedLabel;

    private JLabel gainersTab;
    private JLabel losersTab;
    private JComboBox<String>                                sortDropdown;
    private JComboBox<BankPriceChangesConfig.PanelItemCount> countDropdown;
    private JComboBox<String>                                priceModeDropdown;
    private JComboBox<BankPriceChangesConfig.TimePeriod>     timePeriodDropdown;
    private JButton placeholderBtn;
    private JTextField minPctField;
    private JTextField minGpField;

    private boolean syncingFromConfig = false;

    @Inject
    BankPriceChangesPanel(BankPriceChangesPlugin plugin, BankPriceChangesConfig config,
                          ItemManager itemManager, ConfigManager configManager)
    {
        super(false);
        this.plugin        = plugin;
        this.config        = config;
        this.itemManager   = itemManager;
        this.configManager = configManager;
        this.displayCount  = config.panelItemCount().count;
        buildUi();
    }

    private void buildUi()
    {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // ── Title ─────────────────────────────────────────────
        JLabel title = new JLabel("BANK PRICE CHANGES");
        title.setForeground(Color.WHITE);
        title.setHorizontalAlignment(SwingConstants.CENTER);
        title.setBorder(new EmptyBorder(8, 0, 6, 0));
        title.setFont(title.getFont().deriveFont(Font.BOLD, 14f));

        // ── Tab strip ─────────────────────────────────────────
        gainersTab = new JLabel("GAINERS", SwingConstants.CENTER);
        losersTab  = new JLabel("LOSERS",  SwingConstants.CENTER);
        gainersTab.setOpaque(true);
        losersTab.setOpaque(true);
        gainersTab.setFont(gainersTab.getFont().deriveFont(Font.BOLD, 14f));
        losersTab.setFont(losersTab.getFont().deriveFont(Font.BOLD, 14f));
        gainersTab.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        losersTab.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        gainersTab.addMouseListener(new MouseAdapter()
        {
            @Override public void mouseClicked(MouseEvent e)
            { showGainers = true; updateTabAppearance(); rebuild(); }
        });
        losersTab.addMouseListener(new MouseAdapter()
        {
            @Override public void mouseClicked(MouseEvent e)
            { showGainers = false; updateTabAppearance(); rebuild(); }
        });

        JPanel tabStrip = new JPanel(new GridLayout(1, 2));
        tabStrip.setBackground(ColorScheme.DARK_GRAY_COLOR);
        tabStrip.add(gainersTab);
        tabStrip.add(losersTab);

        // ── Dropdowns ─────────────────────────────────────────
        sortDropdown = makeDropdown(SORT_OPTIONS);
        sortDropdown.addActionListener(e ->
        {
            if (syncingFromConfig) return;
            showByPercent = sortDropdown.getSelectedIndex() == 1;
            configManager.setConfiguration(CONFIG_GROUP, "showByPercent", showByPercent);
            rebuild();
        });

        countDropdown = makeDropdown(BankPriceChangesConfig.PanelItemCount.values());
        countDropdown.addActionListener(e ->
        {
            if (syncingFromConfig) return;
            BankPriceChangesConfig.PanelItemCount sel =
                (BankPriceChangesConfig.PanelItemCount) countDropdown.getSelectedItem();
            if (sel == null) return;
            displayCount = sel.count;
            configManager.setConfiguration(CONFIG_GROUP, "panelItemCount", sel);
            rebuild();
        });

        priceModeDropdown = makeDropdown(PRICE_MODE_OPTIONS);
        priceModeDropdown.setToolTipText(
            "<html><b>Sell offer (low):</b> the lowest active sell price — what you receive when selling instantly<br>" +
            "<b>Buy offer (high):</b> the highest active buy price — what you pay when buying instantly</html>"
        );
        priceModeDropdown.addActionListener(e ->
        {
            if (syncingFromConfig) return;
            BankPriceChangesConfig.PriceMode mode = priceModeDropdown.getSelectedIndex() == 0
                ? BankPriceChangesConfig.PriceMode.LOW
                : BankPriceChangesConfig.PriceMode.HIGH;
            configManager.setConfiguration(CONFIG_GROUP, "priceMode", mode);
            rebuild();
        });

        timePeriodDropdown = makeDropdown(BankPriceChangesConfig.TimePeriod.values());
        timePeriodDropdown.setRenderer(new DefaultListCellRenderer()
        {
            @Override public Component getListCellRendererComponent(
                    JList<?> list, Object value, int index, boolean selected, boolean focus)
            {
                super.getListCellRendererComponent(list, value, index, selected, focus);
                if (value instanceof BankPriceChangesConfig.TimePeriod)
                    setText(PERIOD_LABELS.getOrDefault(value, value.toString()));
                setBackground(selected ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
                setForeground(Color.WHITE);
                setBorder(new EmptyBorder(2, 6, 2, 6));
                return this;
            }
        });
        timePeriodDropdown.addActionListener(e ->
        {
            if (syncingFromConfig) return;
            BankPriceChangesConfig.TimePeriod sel =
                (BankPriceChangesConfig.TimePeriod) timePeriodDropdown.getSelectedItem();
            if (sel != null) setTimePeriod(sel);
        });

        // ── Controls: GridBagLayout so labels auto-size and dropdowns fill ──
        JPanel dropdownPanel = new JPanel(new GridBagLayout());
        dropdownPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        dropdownPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        GridBagConstraints lc = new GridBagConstraints();
        lc.gridx  = 0;
        lc.anchor = GridBagConstraints.WEST;
        lc.insets = new Insets(2, 0, 2, 8);

        GridBagConstraints dc = new GridBagConstraints();
        dc.gridx    = 1;
        dc.weightx  = 1.0;
        dc.fill     = GridBagConstraints.HORIZONTAL;
        dc.insets   = new Insets(2, 0, 2, 0);

        lc.gridy = 0; dc.gridy = 0;
        dropdownPanel.add(makeSmallLabel("Display:"),  lc);
        dropdownPanel.add(sortDropdown,                dc);

        lc.gridy = 1; dc.gridy = 1;
        dropdownPanel.add(makeSmallLabel("Items:"),    lc);
        dropdownPanel.add(countDropdown,               dc);

        lc.gridy = 2; dc.gridy = 2;
        dropdownPanel.add(makeSmallLabel("Price:"),    lc);
        dropdownPanel.add(priceModeDropdown,           dc);

        lc.gridy = 3; dc.gridy = 3;
        dropdownPanel.add(makeSmallLabel("Timestep:"), lc);
        dropdownPanel.add(timePeriodDropdown,          dc);

        // ── Threshold inputs ───────────────────────────────────
        minPctField = makeThresholdField(4);
        minGpField  = makeThresholdField(5);

        minPctField.addFocusListener(new FocusAdapter()
        { @Override public void focusLost(FocusEvent e) { commitMinPct(); } });
        minPctField.addActionListener(e -> commitMinPct());

        minGpField.addFocusListener(new FocusAdapter()
        { @Override public void focusLost(FocusEvent e) { commitMinGp(); } });
        minGpField.addActionListener(e -> commitMinGp());

        JPanel thresholdRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        thresholdRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        thresholdRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        thresholdRow.add(makeSmallLabel("Min %:"));
        thresholdRow.add(minPctField);
        thresholdRow.add(makeSmallLabel("Min GP:"));
        thresholdRow.add(minGpField);

        // ── Placeholder toggle on its own row ──────────────────
        placeholderBtn = makeControlButton("Placeholders ✓");
        placeholderBtn.setToolTipText("Include bank placeholder items in the overlay and panel");
        placeholderBtn.addActionListener(e ->
        {
            if (!syncingFromConfig)
                configManager.setConfiguration(CONFIG_GROUP, "includePlaceholders",
                    !config.includePlaceholders());
        });

        JPanel phRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        phRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        phRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        phRow.add(placeholderBtn);

        // ── Controls container ─────────────────────────────────
        JPanel controls = new JPanel();
        controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
        controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
        controls.setBorder(new EmptyBorder(6, 6, 6, 6));
        controls.add(dropdownPanel);
        controls.add(Box.createVerticalStrut(6));
        controls.add(thresholdRow);
        controls.add(Box.createVerticalStrut(2));
        controls.add(phRow);

        JPanel top = new JPanel(new BorderLayout());
        top.setBackground(ColorScheme.DARK_GRAY_COLOR);
        top.add(title,    BorderLayout.NORTH);
        top.add(tabStrip, BorderLayout.CENTER);
        top.add(controls, BorderLayout.SOUTH);

        // ── Item list ──────────────────────────────────────────
        itemListPanel = new JPanel();
        itemListPanel.setLayout(new BoxLayout(itemListPanel, BoxLayout.Y_AXIS));
        itemListPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        itemListPanel.setBorder(new EmptyBorder(4, 4, 4, 4));

        // Wrapper keeps items packed to the top inside the scroll pane
        JPanel listWrapper = new JPanel(new BorderLayout());
        listWrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        listWrapper.add(itemListPanel, BorderLayout.NORTH);

        JScrollPane scroll = new JScrollPane(listWrapper);
        scroll.setBorder(null);
        scroll.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        scroll.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);

        // ── Footer ─────────────────────────────────────────────
        updatedLabel = new JLabel("Updated: --:--");
        updatedLabel.setForeground(Color.GRAY);
        updatedLabel.setFont(updatedLabel.getFont().deriveFont(13f));

        JButton refreshBtn = makeControlButton("Refresh");
        refreshBtn.setToolTipText("Refresh Now");
        refreshBtn.addActionListener(e -> plugin.refreshNow());

        JPanel footer = new JPanel(new BorderLayout(4, 0));
        footer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        footer.setBorder(new EmptyBorder(4, 6, 4, 4));
        footer.add(updatedLabel, BorderLayout.CENTER);
        footer.add(refreshBtn,   BorderLayout.EAST);

        add(top,    BorderLayout.NORTH);
        add(scroll, BorderLayout.CENTER);
        add(footer, BorderLayout.SOUTH);

        updateTabAppearance();
        updatePlaceholderButton();
        syncFromConfig();
    }

    // ── Helpers ───────────────────────────────────────────────

    private <T> JComboBox<T> makeDropdown(T[] items)
    {
        JComboBox<T> combo = new JComboBox<>(items);
        combo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        combo.setForeground(Color.WHITE);
        combo.setFont(combo.getFont().deriveFont(13f));
        combo.setFocusable(false);
        combo.setRenderer(new DefaultListCellRenderer()
        {
            @Override public Component getListCellRendererComponent(
                    JList<?> list, Object value, int index, boolean selected, boolean focus)
            {
                super.getListCellRendererComponent(list, value, index, selected, focus);
                setBackground(selected ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
                setForeground(Color.WHITE);
                setBorder(new EmptyBorder(2, 6, 2, 6));
                return this;
            }
        });
        return combo;
    }

    private JButton makeControlButton(String text)
    {
        JButton btn = new JButton(text);
        btn.setFocusPainted(false);
        btn.setFont(btn.getFont().deriveFont(13f));
        btn.setMargin(new Insets(2, 5, 2, 5));
        btn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        btn.setForeground(Color.GRAY);
        btn.setBorderPainted(false);
        btn.setOpaque(true);
        return btn;
    }

    private JTextField makeThresholdField(int cols)
    {
        JTextField field = new JTextField(cols);
        field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        field.setForeground(Color.WHITE);
        field.setCaretColor(Color.WHITE);
        field.setFont(field.getFont().deriveFont(13f));
        field.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 1));
        return field;
    }

    private JLabel makeSmallLabel(String text)
    {
        JLabel lbl = new JLabel(text);
        lbl.setForeground(Color.GRAY);
        lbl.setFont(lbl.getFont().deriveFont(13f));
        return lbl;
    }

    private void setTimePeriod(BankPriceChangesConfig.TimePeriod period)
    {
        configManager.setConfiguration(CONFIG_GROUP, "timePeriod", period);
    }

    private void commitMinPct()
    {
        if (syncingFromConfig) return;
        try
        {
            double val = Double.parseDouble(minPctField.getText().trim());
            configManager.setConfiguration(CONFIG_GROUP, "minThreshold", val);
        }
        catch (NumberFormatException ignored) {}
    }

    private void commitMinGp()
    {
        if (syncingFromConfig) return;
        try
        {
            int val = Integer.parseInt(minGpField.getText().trim());
            configManager.setConfiguration(CONFIG_GROUP, "minGpThreshold", val);
        }
        catch (NumberFormatException ignored) {}
    }

    // ── Config sync ───────────────────────────────────────────

    public void syncFromConfig()
    {
        syncingFromConfig = true;
        showByPercent = config.showByPercent();
        displayCount  = config.panelItemCount().count;

        sortDropdown.setSelectedIndex(showByPercent ? 1 : 0);
        countDropdown.setSelectedItem(config.panelItemCount());
        priceModeDropdown.setSelectedIndex(
            config.priceMode() == BankPriceChangesConfig.PriceMode.LOW ? 0 : 1);
        timePeriodDropdown.setSelectedItem(config.timePeriod());
        updatePlaceholderButton();

        minPctField.setText(String.valueOf(config.minThreshold()));
        minGpField.setText(String.valueOf(config.minGpThreshold()));
        syncingFromConfig = false;
        if (!allEntries.isEmpty()) rebuild();
    }

    // ── Appearance updaters ───────────────────────────────────

    private void updateTabAppearance()
    {
        if (showGainers)
        {
            gainersTab.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            gainersTab.setForeground(COLOR_GAIN);
            gainersTab.setBorder(BorderFactory.createCompoundBorder(
                new MatteBorder(0, 0, 2, 0, COLOR_GAIN), new EmptyBorder(6, 0, 4, 0)));
            losersTab.setBackground(ColorScheme.DARK_GRAY_COLOR);
            losersTab.setForeground(Color.GRAY);
            losersTab.setBorder(new EmptyBorder(6, 0, 6, 0));
        }
        else
        {
            losersTab.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            losersTab.setForeground(COLOR_LOSS);
            losersTab.setBorder(BorderFactory.createCompoundBorder(
                new MatteBorder(0, 0, 2, 0, COLOR_LOSS), new EmptyBorder(6, 0, 4, 0)));
            gainersTab.setBackground(ColorScheme.DARK_GRAY_COLOR);
            gainersTab.setForeground(Color.GRAY);
            gainersTab.setBorder(new EmptyBorder(6, 0, 6, 0));
        }
    }

    private void updatePlaceholderButton()
    {
        boolean on = config.includePlaceholders();
        placeholderBtn.setForeground(on ? COLOR_GAIN : Color.GRAY);
        placeholderBtn.setText(on ? "Placeholders ✓" : "Placeholders ✗");
    }

    // ── Data ──────────────────────────────────────────────────

    public void updateData(List<PanelItemEntry> entries)
    {
        allEntries = entries;
        updatedLabel.setText("Updated: " + LocalTime.now().format(DateTimeFormatter.ofPattern("HH:mm")));
        rebuild();
    }

    private void rebuild()
    {
        BankPriceChangesConfig.PriceMode mode = config.priceMode();

        Comparator<PanelItemEntry> comparator = showByPercent
            ? Comparator.comparingDouble(e -> Math.abs(e.priceData.getChangePct(mode)))
            : Comparator.comparingInt(e -> Math.abs(e.priceData.getChange(mode)));
        comparator = comparator.reversed();

        itemListPanel.removeAll();

        allEntries.stream()
            .filter(e ->
            {
                // Exclude items with no historical data for this period
                int prev = mode == BankPriceChangesConfig.PriceMode.HIGH
                    ? e.priceData.getPreviousHigh() : e.priceData.getPreviousLow();
                return prev != 0;
            })
            .filter(e -> showGainers
                ? e.priceData.getChange(mode) > 0
                : e.priceData.getChange(mode) < 0)
            .filter(e -> Math.abs(e.priceData.getChangePct(mode)) >= config.minThreshold())
            .filter(e -> Math.abs(e.priceData.getChange(mode))    >= config.minGpThreshold())
            .sorted(comparator)
            .limit(displayCount)
            .forEach(e ->
            {
                itemListPanel.add(buildCard(e, mode));
                itemListPanel.add(Box.createVerticalStrut(4));
            });

        itemListPanel.revalidate();
        itemListPanel.repaint();
    }

    private JPanel buildCard(PanelItemEntry entry, BankPriceChangesConfig.PriceMode mode)
    {
        int curPrice  = mode == BankPriceChangesConfig.PriceMode.HIGH
            ? entry.priceData.getCurrentHigh()  : entry.priceData.getCurrentLow();
        int prevPrice = mode == BankPriceChangesConfig.PriceMode.HIGH
            ? entry.priceData.getPreviousHigh() : entry.priceData.getPreviousLow();

        int change    = entry.priceData.getChange(mode);
        double pct    = entry.priceData.getChangePct(mode);

        boolean isGain    = change >= 0;
        Color accentColor = isGain ? COLOR_GAIN : COLOR_LOSS;
        String sign       = isGain ? "+" : "";

        // ── Card container ─────────────────────────────────────
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        card.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(accentColor, 1),
            new EmptyBorder(5, 7, 5, 7)
        ));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);

        // ── Row 1: icon + item name ────────────────────────────
        JLabel spriteLabel = new JLabel();
        spriteLabel.setPreferredSize(new Dimension(36, 32));
        try
        {
            BufferedImage img = itemManager.getImage(entry.itemId, 1, false);
            if (img != null) spriteLabel.setIcon(new ImageIcon(img));
        }
        catch (Exception ignored) {}

        JLabel nameLabel = new JLabel(entry.itemName);
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD, 13f));

        JPanel nameRow = new JPanel(new BorderLayout(6, 0));
        nameRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        nameRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        nameRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        nameRow.add(spriteLabel, BorderLayout.WEST);
        nameRow.add(nameLabel,   BorderLayout.CENTER);

        // ── Row 2: Now | Then | Change ────────────────────────
        JPanel priceRow = new JPanel(new GridLayout(1, 3, 2, 0));
        priceRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        priceRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        priceRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 36));
        priceRow.setBorder(new EmptyBorder(4, 0, 0, 0));

        String chgText = showByPercent
            ? sign + String.format("%.1f%%", pct)
            : sign + PriceFormatter.formatGp(change);

        priceRow.add(makePriceCell("Now",    PriceFormatter.formatGp(curPrice),  Color.WHITE));
        priceRow.add(makePriceCell("Then",   PriceFormatter.formatGp(prevPrice), Color.WHITE));
        priceRow.add(makePriceCell("Change", chgText,                            accentColor));

        card.add(nameRow);
        card.add(priceRow);

        // Hover highlight
        Color normalBg = ColorScheme.DARKER_GRAY_COLOR;
        Color hoverBg  = ColorScheme.DARK_GRAY_HOVER_COLOR;
        MouseAdapter hover = new MouseAdapter()
        {
            @Override public void mouseEntered(MouseEvent e)
            { setCardBackground(card, nameRow, priceRow, hoverBg); }
            @Override public void mouseExited(MouseEvent e)
            { setCardBackground(card, nameRow, priceRow, normalBg); }
        };
        card.addMouseListener(hover);
        nameRow.addMouseListener(hover);
        priceRow.addMouseListener(hover);

        return card;
    }

    private JPanel makePriceCell(String header, String value, Color valueColor)
    {
        JLabel headerLabel = new JLabel(header);
        headerLabel.setForeground(COLOR_LABEL);
        headerLabel.setFont(headerLabel.getFont().deriveFont(12f));

        JLabel valueLabel = new JLabel(value);
        valueLabel.setForeground(valueColor);
        valueLabel.setFont(valueLabel.getFont().deriveFont(Font.BOLD, 13f));

        JPanel cell = new JPanel();
        cell.setLayout(new BoxLayout(cell, BoxLayout.Y_AXIS));
        cell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        headerLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        valueLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        cell.add(headerLabel);
        cell.add(valueLabel);
        return cell;
    }

    private void setCardBackground(JPanel card, JPanel nameRow, JPanel priceRow, Color bg)
    {
        card.setBackground(bg);
        nameRow.setBackground(bg);
        priceRow.setBackground(bg);
        for (Component c : priceRow.getComponents())
        {
            if (c instanceof JPanel) ((JPanel) c).setBackground(bg);
        }
    }

    public static class PanelItemEntry
    {
        final int itemId;
        final String itemName;
        final PriceData priceData;

        public PanelItemEntry(int itemId, String itemName, PriceData priceData)
        {
            this.itemId    = itemId;
            this.itemName  = itemName;
            this.priceData = priceData;
        }
    }
}

package com.bankpricechanges;

import com.google.gson.Gson;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import okhttp3.OkHttpClient;

import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemMapping;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicBoolean;

@Slf4j
@PluginDescriptor(
    name = "Bank Price Changes",
    description = "Shows price changes directly on bank items",
    tags = {"bank", "price", "ge", "value"}
)
public class BankPriceChangesPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ItemManager itemManager;
    @Inject private OverlayManager overlayManager;
    @Inject private BankPriceChangesOverlay overlay;
    @Inject private BankPriceChangesConfig config;
    @Inject private Gson gson;
    @Inject private OkHttpClient okHttpClient;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ClientThread clientThread;
    @Inject private BankPriceChangesPanel panel;

    private WikiPriceClient wikiPriceClient;
    private final Map<Integer, PriceData> priceChanges = new ConcurrentHashMap<>();
    private final Set<Integer> bankItemIds = ConcurrentHashMap.newKeySet();
    private final Set<Integer> fetchItemIds = ConcurrentHashMap.newKeySet();
    private ExecutorService executor;

    // Per-period price cache
    private final Map<BankPriceChangesConfig.TimePeriod, Map<Integer, PriceData>>
        priceCache = new ConcurrentHashMap<>();

    // Per-period panel entries
    private final Map<BankPriceChangesConfig.TimePeriod, List<BankPriceChangesPanel.PanelItemEntry>>
        entriesByPeriod = new ConcurrentHashMap<>();

    // Last-fetch timestamps — keyed by period for bulk, and by a sentinel for the two timeseries groups
    private final Map<BankPriceChangesConfig.TimePeriod, Instant>
        lastFetchByPeriod = new ConcurrentHashMap<>();

    // In-flight guards
    private final AtomicBoolean fetchingTimeseries = new AtomicBoolean(false);
    private final Set<BankPriceChangesConfig.TimePeriod>
        fetchingBulk = ConcurrentHashMap.newKeySet();

    private volatile Instant lastManualRefresh = Instant.EPOCH;
    private static final int MANUAL_REFRESH_COOLDOWN_SECONDS = 30;
    private static final int STALE_MINUTES = 5;

    // Sentinel period used to track staleness of the shared 6h timeseries fetch
    private static final BankPriceChangesConfig.TimePeriod SENTINEL_6H =
        BankPriceChangesConfig.TimePeriod.SIX_HOURS;
    // Sentinel period used to track staleness of the shared daily timeseries fetch (24h/1w/1m/1y)
    private static final BankPriceChangesConfig.TimePeriod SENTINEL_DAILY =
        BankPriceChangesConfig.TimePeriod.TWENTY_FOUR_HOURS;

    private NavigationButton navButton;
    private ItemContainer bankContainer;

    @Provides
    BankPriceChangesConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BankPriceChangesConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        wikiPriceClient = new WikiPriceClient(okHttpClient, gson);
        executor = Executors.newFixedThreadPool(4);

        navButton = NavigationButton.builder()
            .tooltip("Bank Price Changes")
            .icon(buildIcon())
            .priority(7)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);

        log.info("Bank Price Changes plugin started");
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        clientToolbar.removeNavigation(navButton);
        executor.shutdown();
        priceChanges.clear();
        bankItemIds.clear();
        priceCache.clear();
        entriesByPeriod.clear();
        lastFetchByPeriod.clear();
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.BANK.getId())
        {
            bankContainer = event.getItemContainer();
            rescanBank();
            log.info("Bank container changed ({} unique items), triggering price refresh", bankItemIds.size());
            refreshAllPeriods();
        }
    }

    void rescanBank()
    {
        if (bankContainer == null) return;
        bankItemIds.clear();
        for (Item item : bankContainer.getItems())
        {
            if (item.getId() < 0) continue;
            if (!config.includePlaceholders()
                    && itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() != -1)
            {
                continue;
            }
            bankItemIds.add(itemManager.canonicalize(item.getId()));
        }
        fetchItemIds.clear();
        fetchItemIds.addAll(bankItemIds);
        for (Integer bankId : bankItemIds)
        {
            Collection<ItemMapping> mappings = ItemMapping.map(bankId);
            if (mappings != null)
            {
                for (ItemMapping m : mappings)
                {
                    fetchItemIds.add(m.getTradeableItem());
                }
            }
        }
    }

    void refreshAllPeriods()
    {
        executor.submit(this::refreshBulkPeriod5m);
        executor.submit(this::refreshBulkPeriod1h);
        executor.submit(this::refreshSixHourPeriod);
        executor.submit(this::refreshDailyPeriods);
    }

    private void refreshBulkPeriod5m()
    {
        refreshBulkPeriod(BankPriceChangesConfig.TimePeriod.FIVE_MIN);
    }

    private void refreshBulkPeriod1h()
    {
        refreshBulkPeriod(BankPriceChangesConfig.TimePeriod.ONE_HOUR);
    }

    private void refreshBulkPeriod(BankPriceChangesConfig.TimePeriod period)
    {
        Instant last = lastFetchByPeriod.getOrDefault(period, Instant.EPOCH);
        if (Duration.between(last, Instant.now()).toMinutes() < STALE_MINUTES) return;
        if (!fetchingBulk.add(period)) return;
        lastFetchByPeriod.put(period, Instant.now());
        try
        {
            Map<Integer, PriceData> data = wikiPriceClient.fetchBulkPeriod(period);
            priceCache.put(period, data);
            log.info("Fetched bulk price data for {} items ({})", data.size(), period);
            pushToPanel(period, data);
        }
        catch (Exception e)
        {
            log.warn("Failed to fetch bulk period {}", period, e);
        }
        finally
        {
            fetchingBulk.remove(period);
        }
    }

    private void refreshSixHourPeriod()
    {
        Instant last = lastFetchByPeriod.getOrDefault(SENTINEL_6H, Instant.EPOCH);
        if (Duration.between(last, Instant.now()).toMinutes() < STALE_MINUTES) return;
        if (!fetchingTimeseries.compareAndSet(false, true)) return;
        lastFetchByPeriod.put(SENTINEL_6H, Instant.now());
        try
        {
            Set<Integer> ids = Set.copyOf(fetchItemIds);
            Map<Integer, PriceData> data = wikiPriceClient.fetchSixHourPeriod(ids);
            priceCache.put(BankPriceChangesConfig.TimePeriod.SIX_HOURS, data);
            log.info("Fetched 6h timeseries for {} items", data.size());
            pushToPanel(BankPriceChangesConfig.TimePeriod.SIX_HOURS, data);
        }
        catch (Exception e)
        {
            log.warn("Failed to fetch 6h timeseries", e);
        }
        finally
        {
            fetchingTimeseries.set(false);
        }
    }

    private void refreshDailyPeriods()
    {
        Instant last = lastFetchByPeriod.getOrDefault(SENTINEL_DAILY, Instant.EPOCH);
        if (Duration.between(last, Instant.now()).toMinutes() < STALE_MINUTES) return;
        // Use a separate atomic for daily to allow 6h and daily to run concurrently
        // Simple staleness + period-keyed guard is enough here since executor is multi-threaded
        lastFetchByPeriod.put(SENTINEL_DAILY, Instant.now());
        try
        {
            Set<Integer> ids = Set.copyOf(fetchItemIds);
            Map<BankPriceChangesConfig.TimePeriod, Map<Integer, PriceData>> allData =
                wikiPriceClient.fetchDailyPeriods(ids);

            for (Map.Entry<BankPriceChangesConfig.TimePeriod, Map<Integer, PriceData>> entry
                : allData.entrySet())
            {
                priceCache.put(entry.getKey(), entry.getValue());
                log.info("Fetched daily timeseries ({}) for {} items",
                    entry.getKey(), entry.getValue().size());
                pushToPanel(entry.getKey(), entry.getValue());
            }
        }
        catch (Exception e)
        {
            log.warn("Failed to fetch daily timeseries periods", e);
        }
    }

    /** Resolves component-item names on the client thread, then pushes entries to the panel. */
    private void pushToPanel(BankPriceChangesConfig.TimePeriod period, Map<Integer, PriceData> data)
    {
        clientThread.invokeLater(() ->
        {
            List<BankPriceChangesPanel.PanelItemEntry> entries = new ArrayList<>();
            for (Integer bankId : bankItemIds)
            {
                PriceData priceData = data.get(bankId);
                if (priceData == null)
                {
                    Collection<ItemMapping> mappings = ItemMapping.map(bankId);
                    if (mappings == null) continue;

                    long curHighTotal = 0, curLowTotal = 0;
                    long prevHighTotal = 0, prevLowTotal = 0;
                    boolean allFound = true;

                    for (ItemMapping mapping : mappings)
                    {
                        PriceData component = data.get(mapping.getTradeableItem());
                        if (component == null) { allFound = false; break; }
                        curHighTotal  += (long) component.getCurrentHigh()  * mapping.getQuantity();
                        curLowTotal   += (long) component.getCurrentLow()   * mapping.getQuantity();
                        prevHighTotal += (long) component.getPreviousHigh() * mapping.getQuantity();
                        prevLowTotal  += (long) component.getPreviousLow()  * mapping.getQuantity();
                    }
                    if (!allFound || (prevHighTotal == 0 && prevLowTotal == 0)) continue;
                    priceData = PriceData.of(
                        (int) curHighTotal, (int) curLowTotal,
                        (int) prevHighTotal, (int) prevLowTotal
                    );
                    data.put(bankId, priceData);
                }
                String itemName = itemManager.getItemComposition(bankId).getName();
                entries.add(new BankPriceChangesPanel.PanelItemEntry(bankId, itemName, priceData));
            }
            entriesByPeriod.put(period, entries);

            if (period == config.timePeriod())
            {
                priceChanges.clear();
                priceChanges.putAll(data);
                SwingUtilities.invokeLater(() -> panel.updateData(entries));
            }
        });
    }

    public void refreshNow()
    {
        Instant now = Instant.now();
        if (Duration.between(lastManualRefresh, now).getSeconds() < MANUAL_REFRESH_COOLDOWN_SECONDS)
        {
            log.debug("Manual refresh ignored — cooldown active");
            return;
        }
        lastManualRefresh = now;
        lastFetchByPeriod.clear();
        refreshAllPeriods();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"bankpricechanges".equals(event.getGroup())) return;

        SwingUtilities.invokeLater(() -> panel.syncFromConfig());

        switch (event.getKey())
        {
            case "timePeriod":
                BankPriceChangesConfig.TimePeriod newPeriod = config.timePeriod();
                Map<Integer, PriceData> cached = priceCache.get(newPeriod);
                List<BankPriceChangesPanel.PanelItemEntry> cachedEntries = entriesByPeriod.get(newPeriod);
                Instant lastForPeriod = lastFetchByPeriod.get(getStalenessKey(newPeriod));
                boolean fresh = lastForPeriod != null
                    && Duration.between(lastForPeriod, Instant.now()).toMinutes() < STALE_MINUTES;

                if (cached != null && cachedEntries != null && fresh)
                {
                    priceChanges.clear();
                    priceChanges.putAll(cached);
                    SwingUtilities.invokeLater(() -> panel.updateData(cachedEntries));
                }
                else
                {
                    executor.submit(() -> fetchPeriod(newPeriod));
                }
                break;
            case "includePlaceholders":
                clientThread.invokeLater(() ->
                {
                    rescanBank();
                    refreshAllPeriods();
                });
                break;
        }
    }

    /** Returns the staleness-tracking key for a given period. */
    private BankPriceChangesConfig.TimePeriod getStalenessKey(BankPriceChangesConfig.TimePeriod period)
    {
        switch (period)
        {
            case FIVE_MIN:      return BankPriceChangesConfig.TimePeriod.FIVE_MIN;
            case ONE_HOUR:      return BankPriceChangesConfig.TimePeriod.ONE_HOUR;
            case SIX_HOURS:     return SENTINEL_6H;
            default:            return SENTINEL_DAILY; // 24h, 1w, 1m, 1y
        }
    }

    /** Fetches only the group containing the given period (used on cache miss after period switch). */
    private void fetchPeriod(BankPriceChangesConfig.TimePeriod period)
    {
        switch (period)
        {
            case FIVE_MIN:  refreshBulkPeriod(BankPriceChangesConfig.TimePeriod.FIVE_MIN);  break;
            case ONE_HOUR:  refreshBulkPeriod(BankPriceChangesConfig.TimePeriod.ONE_HOUR);  break;
            case SIX_HOURS: refreshSixHourPeriod(); break;
            default:        refreshDailyPeriods();  break;
        }
    }

    public PriceData getPriceChange(int itemId)
    {
        return priceChanges.get(itemId);
    }

    private static BufferedImage buildIcon()
    {
        BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        g.setColor(new Color(200, 160, 0));
        g.fillRect(1, 10, 3, 5);
        g.fillRect(6, 6, 3, 9);
        g.fillRect(11, 2, 3, 13);

        g.setColor(new Color(255, 220, 80));
        g.fillRect(1, 10, 1, 5);
        g.fillRect(6, 6, 1, 9);
        g.fillRect(11, 2, 1, 13);

        g.dispose();
        return image;
    }
}

package com.bankpricechanges;

import lombok.Value;

@Value
public class PriceData
{
    int currentHigh;
    int currentLow;
    int previousHigh;
    int previousLow;

    public int getChange(BankPriceChangesConfig.PriceMode mode)
    {
        int cur  = mode == BankPriceChangesConfig.PriceMode.HIGH ? currentHigh  : currentLow;
        int prev = mode == BankPriceChangesConfig.PriceMode.HIGH ? previousHigh : previousLow;
        return cur - prev;
    }

    public double getChangePct(BankPriceChangesConfig.PriceMode mode)
    {
        int prev = mode == BankPriceChangesConfig.PriceMode.HIGH ? previousHigh : previousLow;
        return prev != 0 ? (getChange(mode) / (double) prev) * 100.0 : 0.0;
    }

    public static PriceData of(int currentHigh, int currentLow, int previousHigh, int previousLow)
    {
        return new PriceData(currentHigh, currentLow, previousHigh, previousLow);
    }
}

package com.bankpricechanges;

public class PriceFormatter
{
    public static String formatGp(int amount)
    {
        int abs = Math.abs(amount);
        if (abs >= 1_000_000_000) return String.format("%.1fb", amount / 1_000_000_000.0);
        if (abs >= 1_000_000)     return String.format("%.2fm", amount / 1_000_000.0);
        if (abs >= 100_000)       return String.format("%dk",   amount / 1_000);
        if (abs >= 1_000)         return String.format("%.1fk", amount / 1_000.0);
        return String.valueOf(amount);
    }
}

package com.bankpricechanges;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.Dispatcher;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

@Slf4j
public class WikiPriceClient
{
    private static final String BASE_URL = "https://prices.runescape.wiki/api/v1/osrs";
    private static final String USER_AGENT = "bank-price-changes - RuneLite Plugin";

    // Target lookback durations in seconds for each timeseries-based period
    private static final Map<BankPriceChangesConfig.TimePeriod, Long> DAILY_PERIOD_SECONDS;
    static
    {
        DAILY_PERIOD_SECONDS = new EnumMap<>(BankPriceChangesConfig.TimePeriod.class);
        DAILY_PERIOD_SECONDS.put(BankPriceChangesConfig.TimePeriod.TWENTY_FOUR_HOURS, 24L * 3600);
        DAILY_PERIOD_SECONDS.put(BankPriceChangesConfig.TimePeriod.ONE_WEEK,          7L  * 24 * 3600);
        DAILY_PERIOD_SECONDS.put(BankPriceChangesConfig.TimePeriod.ONE_MONTH,         30L * 24 * 3600);
        DAILY_PERIOD_SECONDS.put(BankPriceChangesConfig.TimePeriod.ONE_YEAR,          365L * 24 * 3600);
    }

    private final Gson gson;
    private final OkHttpClient httpClient;
    private final OkHttpClient timeseriesClient;

    public WikiPriceClient(OkHttpClient httpClient, Gson gson)
    {
        this.gson = gson;
        this.httpClient = httpClient;
        Dispatcher d = new Dispatcher();
        d.setMaxRequestsPerHost(20);
        this.timeseriesClient = httpClient.newBuilder().dispatcher(d).build();
    }

    /**
     * Fetches price data for the 5m or 1h bulk endpoint.
     * Returns a map of itemId → PriceData for all tradeable items.
     */
    public Map<Integer, PriceData> fetchBulkPeriod(BankPriceChangesConfig.TimePeriod period)
    {
        Map<Integer, PriceData> result = new HashMap<>();
        try
        {
            JsonObject latestData = fetchJson(BASE_URL + "/latest");
            if (latestData == null || !latestData.has("data"))
            {
                return result;
            }
            JsonObject latestItems = latestData.getAsJsonObject("data");

            String endpoint = period == BankPriceChangesConfig.TimePeriod.FIVE_MIN ? "5m" : "1h";
            JsonObject historicalData = fetchJson(BASE_URL + "/" + endpoint);
            if (historicalData == null || !historicalData.has("data"))
            {
                return result;
            }
            JsonObject historicalItems = historicalData.getAsJsonObject("data");

            for (Map.Entry<String, JsonElement> entry : latestItems.entrySet())
            {
                String idStr = entry.getKey();
                int itemId;
                try { itemId = Integer.parseInt(idStr); }
                catch (NumberFormatException e) { continue; }

                JsonObject currentObj = entry.getValue().getAsJsonObject();
                Integer curHigh = getHigh(currentObj);
                Integer curLow  = getLow(currentObj);
                if (curHigh == null && curLow == null) continue;

                JsonElement histEl = historicalItems.get(idStr);
                if (histEl == null || histEl.isJsonNull()) continue;

                JsonObject histObj = histEl.getAsJsonObject();
                Integer prevHigh = getHigh(histObj);
                Integer prevLow  = getLow(histObj);
                if (prevHigh == null && prevLow == null) continue;

                result.put(itemId, PriceData.of(
                    curHigh  != null ? curHigh  : 0,
                    curLow   != null ? curLow   : 0,
                    prevHigh != null ? prevHigh : 0,
                    prevLow  != null ? prevLow  : 0
                ));
            }
        }
        catch (Exception e)
        {
            log.warn("Failed to fetch bulk price data ({})", period, e);
        }
        return result;
    }

    /**
     * Fires one async timeseries request per item using timestep=6h.
     * Finds the data point whose timestamp is closest to now-6h.
     */
    public Map<Integer, PriceData> fetchSixHourPeriod(Set<Integer> itemIds)
    {
        Map<Integer, PriceData> result = new ConcurrentHashMap<>();
        try
        {
            JsonObject latestData = fetchJson(BASE_URL + "/latest");
            if (latestData == null || !latestData.has("data")) return result;
            JsonObject latestItems = latestData.getAsJsonObject("data");

            Map<Integer, int[]> currentPrices = extractCurrentPrices(latestItems, itemIds);
            if (currentPrices.isEmpty()) return result;

            long targetEpoch = Instant.now().minusSeconds(6L * 3600).getEpochSecond();
            fireTimeseriesRequests(currentPrices, "6h", targetEpoch, result);
        }
        catch (Exception e)
        {
            log.warn("Failed to fetch 6h timeseries data", e);
        }
        return result;
    }

    /**
     * Fires one async timeseries request per item using timestep=24h.
     * From the 365-point response, extracts the closest data point for each of
     * TWENTY_FOUR_HOURS, ONE_WEEK, ONE_MONTH, and ONE_YEAR simultaneously.
     */
    public Map<BankPriceChangesConfig.TimePeriod, Map<Integer, PriceData>> fetchDailyPeriods(
        Set<Integer> itemIds)
    {
        Map<BankPriceChangesConfig.TimePeriod, Map<Integer, PriceData>> results = new EnumMap<>(
            BankPriceChangesConfig.TimePeriod.class);
        for (BankPriceChangesConfig.TimePeriod p : DAILY_PERIOD_SECONDS.keySet())
        {
            results.put(p, new ConcurrentHashMap<>());
        }

        try
        {
            JsonObject latestData = fetchJson(BASE_URL + "/latest");
            if (latestData == null || !latestData.has("data")) return results;
            JsonObject latestItems = latestData.getAsJsonObject("data");

            Map<Integer, int[]> currentPrices = extractCurrentPrices(latestItems, itemIds);
            if (currentPrices.isEmpty()) return results;

            long now = Instant.now().getEpochSecond();
            List<CompletableFuture<Void>> futures = new ArrayList<>();

            for (Map.Entry<Integer, int[]> entry : currentPrices.entrySet())
            {
                int itemId = entry.getKey();
                int[] curPrices = entry.getValue(); // [high, low]

                CompletableFuture<Void> future = new CompletableFuture<>();
                futures.add(future);

                String url = BASE_URL + "/timeseries?timestep=24h&id=" + itemId;
                Request request = new Request.Builder()
                    .url(url)
                    .header("User-Agent", USER_AGENT)
                    .build();

                timeseriesClient.newCall(request).enqueue(new Callback()
                {
                    @Override
                    public void onFailure(Call call, IOException e)
                    {
                        log.warn("Daily timeseries request failed for item {}", itemId, e);
                        future.complete(null);
                    }

                    @Override
                    public void onResponse(Call call, Response response) throws IOException
                    {
                        try
                        {
                            if (!response.isSuccessful() || response.body() == null)
                            {
                                log.warn("Daily timeseries unsuccessful for item {}: {}", itemId, response.code());
                                return;
                            }
                            JsonObject json = gson.fromJson(response.body().charStream(), JsonObject.class);
                            if (json == null || !json.has("data")) return;

                            JsonArray dataPoints = json.getAsJsonArray("data");
                            if (dataPoints == null || dataPoints.size() == 0) return;

                            for (Map.Entry<BankPriceChangesConfig.TimePeriod, Long> pe
                                : DAILY_PERIOD_SECONDS.entrySet())
                            {
                                long targetEpoch = now - pe.getValue();
                                JsonObject best = findClosestPoint(dataPoints, targetEpoch);
                                if (best == null) continue;

                                Integer prevHigh = getHigh(best);
                                Integer prevLow  = getLow(best);
                                if (prevHigh == null && prevLow == null) continue;

                                results.get(pe.getKey()).put(itemId, PriceData.of(
                                    curPrices[0],
                                    curPrices[1],
                                    prevHigh != null ? prevHigh : 0,
                                    prevLow  != null ? prevLow  : 0
                                ));
                            }
                        }
                        finally
                        {
                            response.close();
                            future.complete(null);
                        }
                    }
                });
            }

            CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
        }
        catch (Exception e)
        {
            log.warn("Failed to fetch daily timeseries data", e);
        }
        return results;
    }

    // ── Helpers ───────────────────────────────────────────────

    private Map<Integer, int[]> extractCurrentPrices(JsonObject latestItems, Set<Integer> itemIds)
    {
        Map<Integer, int[]> currentPrices = new HashMap<>();
        for (Integer itemId : itemIds)
        {
            JsonElement el = latestItems.get(String.valueOf(itemId));
            if (el == null || el.isJsonNull()) continue;
            JsonObject obj = el.getAsJsonObject();
            Integer high = getHigh(obj);
            Integer low  = getLow(obj);
            if (high == null && low == null) continue;
            currentPrices.put(itemId, new int[]{
                high != null ? high : 0,
                low  != null ? low  : 0
            });
        }
        return currentPrices;
    }

    private void fireTimeseriesRequests(
        Map<Integer, int[]> currentPrices,
        String timestep,
        long targetEpoch,
        Map<Integer, PriceData> result)
    {
        List<CompletableFuture<Void>> futures = new ArrayList<>();

        for (Map.Entry<Integer, int[]> entry : currentPrices.entrySet())
        {
            int itemId = entry.getKey();
            int[] curPrices = entry.getValue();

            CompletableFuture<Void> future = new CompletableFuture<>();
            futures.add(future);

            String url = BASE_URL + "/timeseries?timestep=" + timestep + "&id=" + itemId;
            Request request = new Request.Builder()
                .url(url)
                .header("User-Agent", USER_AGENT)
                .build();

            timeseriesClient.newCall(request).enqueue(new Callback()
            {
                @Override
                public void onFailure(Call call, IOException e)
                {
                    log.warn("Timeseries ({}) request failed for item {}", timestep, itemId, e);
                    future.complete(null);
                }

                @Override
                public void onResponse(Call call, Response response) throws IOException
                {
                    try
                    {
                        if (!response.isSuccessful() || response.body() == null)
                        {
                            log.warn("Timeseries ({}) unsuccessful for item {}: {}",
                                timestep, itemId, response.code());
                            return;
                        }
                        JsonObject json = gson.fromJson(response.body().charStream(), JsonObject.class);
                        if (json == null || !json.has("data")) return;

                        JsonArray dataPoints = json.getAsJsonArray("data");
                        if (dataPoints == null || dataPoints.size() == 0) return;

                        JsonObject best = findClosestPoint(dataPoints, targetEpoch);
                        if (best == null) return;

                        Integer prevHigh = getHigh(best);
                        Integer prevLow  = getLow(best);
                        if (prevHigh == null && prevLow == null) return;

                        result.put(itemId, PriceData.of(
                            curPrices[0],
                            curPrices[1],
                            prevHigh != null ? prevHigh : 0,
                            prevLow  != null ? prevLow  : 0
                        ));
                    }
                    finally
                    {
                        response.close();
                        future.complete(null);
                    }
                }
            });
        }

        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
    }

    private JsonObject findClosestPoint(JsonArray dataPoints, long targetEpoch)
    {
        JsonObject best = null;
        long bestDiff = Long.MAX_VALUE;
        for (JsonElement el : dataPoints)
        {
            JsonObject point = el.getAsJsonObject();
            if (!point.has("timestamp") || point.get("timestamp").isJsonNull()) continue;
            long ts = point.get("timestamp").getAsLong();
            long diff = Math.abs(ts - targetEpoch);
            if (diff < bestDiff)
            {
                bestDiff = diff;
                best = point;
            }
        }
        return best;
    }

    private Integer getHigh(JsonObject obj)
    {
        Integer v = getIntOrNull(obj, "high");
        return v != null ? v : getIntOrNull(obj, "avgHighPrice");
    }

    private Integer getLow(JsonObject obj)
    {
        Integer v = getIntOrNull(obj, "low");
        return v != null ? v : getIntOrNull(obj, "avgLowPrice");
    }

    private Integer getIntOrNull(JsonObject obj, String key)
    {
        if (!obj.has(key) || obj.get(key).isJsonNull()) return null;
        return obj.get(key).getAsInt();
    }

    private JsonObject fetchJson(String url) throws IOException
    {
        Request request = new Request.Builder()
            .url(url)
            .header("User-Agent", USER_AGENT)
            .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                log.warn("Wiki API request failed: {} {}", response.code(), url);
                return null;
            }
            return gson.fromJson(response.body().charStream(), JsonObject.class);
        }
    }
